// 消费者：手动提交，分区数 12，组内最多 12 个消费者有效
@KafkaListener(topics = "order-events", groupId = "points-service", concurrency = "6")
public void consume(ConsumerRecord<String, String> rec, Acknowledgment ack) {
    log.info("partition={} offset={} key={}", rec.partition(), rec.offset(), rec.key());
    pointsService.handleIdempotent(rec.key(), rec.value());
    ack.acknowledge();                        // 处理成功才提交 offset
}

