SendResult r = producer.send(msg, (mqs, m, key) -> {
    int idx = Math.abs(key.hashCode() % mqs.size());
    return mqs.get(idx);
}, order.getOrderNo());

// 消费端：顺序消费，队列加锁、同队列串行
consumer.registerMessageListener((MessageListenerOrderly) (msgs, ctx) -> {
    for (MessageExt m : msgs) {
        try {
            orderStateMachine.apply(parse(m));          // 状态机校验合法迁移
        } catch (Exception e) {
            ctx.setSuspendCurrentQueueTimeMillis(1000);
            return ConsumeOrderlyStatus.SUSPEND_CURRENT_QUEUE_A_MOMENT;  // 原地重试
        }
    }
    return ConsumeOrderlyStatus.SUCCESS;
});

// Kafka 消费端若用线程池：按 key 哈希到固定单线程执行器
ExecutorService[] lanes = IntStream.range(0, 8)
        .mapToObj(i -> Executors.newSingleThreadExecutor()).toArray(ExecutorService[]::new);
void dispatch(ConsumerRecord<String, String> rec) {
    lanes[Math.floorMod(rec.key().hashCode(), lanes.length)].submit(() -> handle(rec));
}
